transforms.code:
# 1.3.0: the map outlines' colours per isolation group - from the popup's own model (its state and whether it is
# picked), no tag reads of its own; the other groups go grey while one is picked
FILL = {'on': '#36664A1F', 'act': '#F2C2004D', 'rst': '#1838D62E', 'stp': '#DC73233D', 'flt': '#C020264D'}
LINE = {'on': '#36664A', 'act': '#B08D00', 'rst': '#1838D6', 'stp': '#DC7323', 'flt': '#C02026'}
out = {}
try:
	gs = list(value or [])
	picked = len([g for g in gs if g['sel']]) > 0
	for g in gs:
		t = str(g['tone'])
		dim = picked and not g['sel']
		out[str(g['id'])] = {'fill': '#00000008' if dim else FILL.get(t, '#0000000F'),
			'line': '#C5CBCC' if dim else LINE.get(t, '#80878A'), 'text': '#9AA3A5' if dim else LINE.get(t, '#80878A'),
			'tip': '%s %s - %s - tap to %s' % (g['no'], g['name'], g['word'], 'show every group' if g['sel'] else 'pick it')}
except:
	pass
return out

